def require(value,message):
    if not value:raise AssertionError(message)
def counts(path):
    assemblies=ET.parse(path).getroot().findall('.//assembly')
    return {key:sum(int(a.attrib.get(key,0)) for a in assemblies) for key in ['total','passed','failed','skipped','errors','not-run']}
